#include <stdio.h>

int set_bit(int n, int pos) { return n | (1 << pos); }
int clear_bit(int n, int pos) { return n & ~(1 << pos); }
int toggle_bit(int n, int pos) { return n ^ (1 << pos); }
int get_bit(int n, int pos) { return (n >> pos) & 1; }

int main() {
    int n = 10; // 1010
    printf("get bit 0: %d\n", get_bit(n, 0));
    printf("set bit 0: %d\n", set_bit(n, 0));
    printf("clear bit 3: %d\n", clear_bit(n, 3));
    printf("toggle bit 1: %d\n", toggle_bit(n, 1));
    return 0;
}
